1	//! Handlers for the `/agents/{name}/runs` resource.
2	//!
3	//! A single handler, [`create_run`], serves all three response shapes keyed on
4	//! the `?stream=` / `?mode=` query:
5	//!
6	//! - default — **one-shot**: block until the run reaches a terminal event, then
7	//!   return the aggregated [`RunResponse`] as JSON.
8	//! - `?stream=sse` — **Server-Sent Events**: stream every [`AgentEvent`] as it
9	//!   is produced, replaying any already-emitted events first.
10	//! - `?mode=async` — **detached**: spawn the run and return `202 Accepted` with
11	//!   the run id immediately; the run continues independently of the connection.
12	//!
13	//! # Execution model
14	//!
15	//! Every request — regardless of mode — spawns one **writer task** that drives
16	//! the agent through the [`Runner`] and drains its event stream into the run's
17	//! [`EventLog`](crate::event_log::EventLog). The response side merely *subscribes*
18	//! to that log. This decoupling is what makes a run replayable (one-shot, SSE,
19	//! and the WebSocket/async-replay transports all read the same log) and is what
20	//! lets `?mode=async` return before the run finishes.
21	//!
22	//! ## Per-session serialization
23	//!
24	//! Before the run is created the handler acquires the per-session lock
25	//! ([`SessionLocks::lock_for`](crate::session::SessionLocks::lock_for)) as an
26	//! *owned* guard and moves it into the writer task, which holds it for the whole
27	//! run and releases it at completion. Two requests carrying the same
28	//! `X-Session-Id` therefore queue: the second blocks on the lock until the
29	//! first run finishes.
30	//!
31	//! ## Cancellation
32	//!
33	//! The run's [`CancellationToken`] is cloned into the [`RunContext`]. For the
34	//! one-shot and SSE modes the response side holds a `DropGuard` over a clone of
35	//! that token, so a client disconnect cancels the run. The detached `?mode=async`
36	//! path deliberately attaches no such guard — the run outlives the connection.
37	
38	use std::{convert::Infallible, sync::Arc, time::Instant};
39	
40	use axum::{
41	    body::Body,
42	    extract::{Path, Query, Request, State},
43	    http::{header::CONTENT_TYPE, request::Parts, HeaderMap, HeaderValue, StatusCode},
44	    response::{sse::Event, IntoResponse, Response, Sse},
45	    Json,
46	};
47	use futures_util::StreamExt;
48	use paigasus_helikon_core::{Agent, AgentEvent, AgentInput, RunConfig, RunContext, Runner};
49	use serde::Deserialize;
50	use tokio::sync::OwnedMutexGuard;
51	use tokio_util::sync::{CancellationToken, DropGuard};
52	use uuid::Uuid;
53	
54	use crate::{
55	    dto::{AsyncAccepted, RunRequest, RunResponse},
56	    error::ServerError,
57	    event_log::{is_terminal, EventLog},
58	    registry::{RunHandle, RunRegistry},
59	    server::AppState,
60	};
61	
62	/// Upper bound on the request body we will buffer before deserializing (2 MiB).
63	const MAX_BODY_BYTES: usize = 2 * 1024 * 1024;
64	
65	/// Query parameters selecting the response transport.
66	#[derive(Debug, Default, Deserialize)]
67	pub(crate) struct RunQuery {
68	    /// `sse` selects the Server-Sent-Events transport.
69	    #[serde(default)]
70	    stream: Option<String>,
71	    /// `async` detaches the run and returns `202 Accepted` immediately.
72	    #[serde(default)]
73	    mode: Option<String>,
74	}
75	
76	impl RunQuery {
77	    /// `true` when the caller requested the detached (`?mode=async`) transport.
78	    fn is_async(&self) -> bool {
79	        self.mode.as_deref() == Some("async")
80	    }
81	
82	    /// `true` when the caller requested the SSE (`?stream=sse`) transport.
83	    fn is_sse(&self) -> bool {
84	        self.stream.as_deref() == Some("sse")
85	    }
86	
87	    /// Reject unrecognised or mutually-exclusive transport selectors.
88	    ///
89	    /// Without this an unknown `?mode=`/`?stream=` value would silently fall
90	    /// back to one-shot, and `?mode=async&stream=sse` would silently prefer
91	    /// async — both surprising the caller. Each is surfaced as a 400 instead.
92	    ///
93	    /// # Errors
94	    ///
95	    /// [`ServerError::BadRequest`] if `mode` is set to anything other than
96	    /// `async`, if `stream` is set to anything other than `sse`, or if both the
97	    /// async and SSE transports are requested together.
98	    fn validate(&self) -> Result<(), ServerError> {
99	        if let Some(mode) = self.mode.as_deref() {
100	            if mode != "async" {
101	                return Err(ServerError::BadRequest(format!(
102	                    "invalid `mode` selector `{mode}`; the only supported value is `async`"
103	                )));
104	            }
105	        }
106	        if let Some(stream) = self.stream.as_deref() {
107	            if stream != "sse" {
108	                return Err(ServerError::BadRequest(format!(
109	                    "invalid `stream` selector `{stream}`; the only supported value is `sse`"
110	                )));
111	            }
112	        }
113	        if self.is_async() && self.is_sse() {
114	            return Err(ServerError::BadRequest(
115	                "`mode=async` and `stream=sse` are mutually exclusive".to_owned(),
116	            ));
117	        }
118	        Ok(())
119	    }
120	}
121	
122	/// `POST /agents/{name}/runs` — start a run of the named agent.
123	///
124	/// See the [module docs](self) for the execution model and the meaning of the
125	/// `?stream=` / `?mode=` query parameters.
126	///
127	/// # Errors
128	///
129	/// - [`ServerError::UnknownAgent`] (404) — no agent with `name` is registered.
130	/// - [`ServerError::Unauthorized`] (401/403) — the context provider rejected the
131	///   request's credentials. (The configured [`AuthLayer`](crate::AuthLayer) runs
132	///   earlier, as router-level middleware.)
133	/// - [`ServerError::BadRequest`] (400) — an invalid or conflicting `?stream=` /
134	///   `?mode=` selector, the body was not valid JSON for a [`RunRequest`], or an
135	///   explicit non-JSON content type was supplied.
136	/// - [`ServerError::RunStart`] (500) — the run failed before emitting any event
137	///   (one-shot mode only).
138	pub(crate) async fn create_run<Ctx: Send + Sync + 'static>(
139	    State(state): State<AppState<Ctx>>,
140	    Path(name): Path<String>,
141	    Query(query): Query<RunQuery>,
142	    request: Request,
143	) -> Result<Response, ServerError> {
144	    // 0. Reject invalid / conflicting transport selectors (400) before doing
145	    //    any work.
146	    query.validate()?;
147	
148	    // Split into parts + body up front; the body is consumed last. Auth has
149	    // already run as router-level middleware, so any identity it inserted is
150	    // present in `parts.extensions` for the context provider below.
151	    let (parts, body) = request.into_parts();
152	
153	    // 1. Resolve the agent (404 if unknown).
154	    let agent = state
155	        .agents
156	        .get(&name)
157	        .cloned()
158	        .ok_or_else(|| ServerError::UnknownAgent(name.clone()))?;
159	
160	    // 2. Deserialize the JSON body (400 on a bad body / non-JSON content type).
161	    let input = read_run_request(&parts, body).await?.into_agent_input();
162	
163	    // 3. Resolve the session from the optional `X-Session-Id` header.
164	    let session_id: Option<String> = parts
165	        .headers
166	        .get("x-session-id")
167	        .and_then(|v| v.to_str().ok())
168	        .map(str::to_owned);
169	    let session = state.sessions.session(session_id.as_deref()).await?;
170	
171	    // 4. Acquire the per-session serialization lock BEFORE creating/spawning the
172	    //    run so that same-session requests queue. The owned guard is moved into
173	    //    the writer task and released when the run completes.
174	    let guard: OwnedMutexGuard<()> = state
175	        .locks
176	        .lock_for(session_id.as_deref())
177	        .lock_owned()
178	        .await;
179	
180	    // 5. Build the run context, then register the run. Building the context
181	    //    before registering avoids leaking a never-terminal registry entry if
182	    //    the context provider fails.
183	    let cancel = CancellationToken::new();
184	    let ctx = state.context.build(&parts, session, cancel.clone()).await?;
185	    let (run_id, handle) = state.registry.create(name, cancel);
186	
187	    // 6. Spawn the writer task: drive the agent and drain its events into the log.
188	    spawn_writer(
189	        Arc::clone(&state.runner),
190	        agent,
191	        ctx,
192	        input,
193	        state.run_config.clone(),
194	        Arc::clone(&handle),
195	        Arc::clone(&state.registry),
196	        run_id,
197	        guard,
198	    );
199	
200	    // 7. Respond per the requested transport.
201	    if query.is_async() {
202	        return Ok(async_response(run_id));
203	    }
204	    if query.is_sse() {
205	        return Ok(sse_response(run_id, &handle));
206	    }
207	    oneshot_response(run_id, &handle).await
208	}
209	
210	/// Read and validate the JSON request body into a [`RunRequest`].
211	///
212	/// Performs a lightweight content-type check: returns 400 on an explicit
213	/// non-JSON content type, while a missing content type is tolerated and the
214	/// bytes are parsed optimistically.
215	async fn read_run_request(parts: &Parts, body: Body) -> Result<RunRequest, ServerError> {
216	    if let Some(ct) = parts
217	        .headers
218	        .get(CONTENT_TYPE)
219	        .and_then(|v| v.to_str().ok())
220	    {
221	        let mime = ct.split(';').next().unwrap_or("").trim();
222	        let is_json = mime == "application/json"
223	            || (mime.starts_with("application/") && mime.ends_with("+json"));
224	        if !is_json {
225	            return Err(ServerError::BadRequest(format!(
226	                "unsupported content type `{mime}`; expected application/json"
227	            )));
228	        }
229	    }
230	
231	    let bytes = axum::body::to_bytes(body, MAX_BODY_BYTES)
232	        .await
233	        .map_err(|e| ServerError::BadRequest(format!("failed to read request body: {e}")))?;
234	
235	    serde_json::from_slice::<RunRequest>(&bytes)
236	        .map_err(|e| ServerError::BadRequest(format!("invalid run request body: {e}")))
237	}
238	
239	/// Drop-guard that records a run's terminal bookkeeping exactly once — on the
240	/// normal path **and** on a panic unwind of the writer task.
241	///
242	/// Both operations are idempotent: [`EventLog::mark_terminal`] just sets a flag,
243	/// and [`RunRegistry::note_terminal`] only stamps when `terminal_at` is still
244	/// `None`. Without this guard a panic mid-drain (e.g. a faulty agent stream)
245	/// would strand every subscriber waiting forever.
246	struct TerminalGuard {
247	    log: Arc<EventLog>,
248	    registry: Arc<RunRegistry>,
249	    run_id: Uuid,
250	}
251	
252	impl Drop for TerminalGuard {
253	    fn drop(&mut self) {
254	        self.log.mark_terminal();
255	        self.registry.note_terminal(self.run_id, Instant::now());
256	    }
257	}
258	
259	/// Spawn the detached writer task that drives one run to completion.
260	///
261	/// Owns every input by value so the task satisfies `'static`. Holds the session
262	/// lock `guard` for the whole run and drops it (releasing the lock) once the run
263	/// is terminal and recorded in the registry. Terminal bookkeeping is owned by a
264	/// [`TerminalGuard`] so it still happens if the agent stream panics mid-drain.
265	#[allow(clippy::too_many_arguments)]
266	fn spawn_writer<Ctx: Send + Sync + 'static>(
267	    runner: Arc<dyn Runner<Ctx>>,
268	    agent: Arc<dyn Agent<Ctx>>,
269	    ctx: RunContext<Ctx>,
270	    input: AgentInput,
271	    run_config: RunConfig,
272	    handle: Arc<RunHandle>,
273	    registry: Arc<RunRegistry>,
274	    run_id: Uuid,
275	    guard: OwnedMutexGuard<()>,
276	) {
277	    tokio::spawn(async move {
278	        // Declared FIRST so it drops LAST: terminal bookkeeping (below) runs
279	        // before the session lock is released, preserving the original ordering.
280	        let _session_lock = guard;
281	        // Declared AFTER the lock so it drops FIRST. Its `Drop` marks the log
282	        // terminal and stamps the registry — even on a panic unwind.
283	        let _terminal = TerminalGuard {
284	            log: Arc::clone(&handle.log),
285	            registry,
286	            run_id,
287	        };
288	
289	        match runner
290	            .run_streamed(agent.as_ref(), ctx, input, run_config)
291	            .await
292	        {
293	            Ok(streaming) => {
294	                let mut events = streaming.events;
295	                while let Some(ev) = events.next().await {
296	                    handle.log.append(ev);
297	                }
298	                // Terminal marking is handled by `_terminal` on scope exit; a
299	                // real `RunCompleted`/`RunFailed` already set the flag, and the
300	                // guard's `mark_terminal` is an idempotent safety net otherwise.
301	            }
302	            Err(e) => {
303	                // The run failed to *start* (no events were ever emitted). Record
304	                // the cause; `_terminal` marks the log terminal so subscribers
305	                // unblock.
306	                *handle
307	                    .start_error
308	                    .lock()
309	                    .expect("start_error mutex poisoned") = Some(e.to_string());
310	            }
311	        }
312	    });
313	}
314	
315	/// Build the `202 Accepted` body for a detached run.
316	fn async_response(run_id: Uuid) -> Response {
317	    (
318	        StatusCode::ACCEPTED,
319	        Json(AsyncAccepted {
320	            run_id: run_id.to_string(),
321	        }),
322	    )
323	        .into_response()
324	}
325	
326	/// Unfold state for the SSE response stream: the live event stream, the cancel
327	/// drop-guard (held for the stream's whole lifetime so a client disconnect
328	/// cancels the run), a clone of the run handle (to synthesize a terminal frame
329	/// on a terminal-less close), and the `saw_terminal` / `done` flags.
330	struct SseState<S> {
331	    events: S,
332	    // Held only for its `Drop` side effect (cancels the run when the SSE
333	    // response — and with it this state — is dropped); never read directly.
334	    #[allow(dead_code)]
335	    disconnect: DropGuard,
336	    handle: Arc<RunHandle>,
337	    saw_terminal: bool,
338	    done: bool,
339	}
340	
341	/// Build the SSE streaming response.
342	///
343	/// The run's cancel `DropGuard` is folded into the stream state so that dropping
344	/// the response (a client disconnect) cancels the run. If the live event stream
345	/// ends without delivering a real terminal event (a start-error, or a stream
346	/// that ended/panicked mid-run), exactly one synthetic `run_failed` frame is
347	/// appended before the SSE stream closes — see
348	/// [`RunHandle::synthetic_terminal_frame`].
349	fn sse_response(run_id: Uuid, handle: &Arc<RunHandle>) -> Response {
350	    let disconnect = handle.cancel.clone().drop_guard();
351	    let events = handle.log.subscribe(0);
352	    let handle = Arc::clone(handle);
353	
354	    let stream = futures_util::stream::unfold(
355	        SseState {
356	            events,
357	            disconnect,
358	            handle,
359	            saw_terminal: false,
360	            done: false,
361	        },
362	        |mut state| async move {
363	            if state.done {
364	                return None;
365	            }
366	            match state.events.next().await {
367	                Some(ev) => {
368	                    state.saw_terminal |= is_terminal(&ev);
369	                    let frame = to_sse_event(&ev);
370	                    Some((Ok::<Event, Infallible>(frame), state))
371	                }
372	                None => {
373	                    // Live stream ended. If no real terminal was delivered, emit
374	                    // exactly one synthetic `run_failed` frame, then finish.
375	                    let synthetic = state.handle.synthetic_terminal_frame(state.saw_terminal)?;
376	                    let frame = to_sse_event(&synthetic);
377	                    state.done = true;
378	                    Some((Ok::<Event, Infallible>(frame), state))
379	                }
380	            }
381	        },
382	    );
383	
384	    let mut response = Sse::new(stream).into_response();
385	    insert_run_id(response.headers_mut(), run_id);
386	    response
387	}
388	
389	/// Build the one-shot response: subscribe, drain to the terminal event, then
390	/// aggregate into a [`RunResponse`].
391	async fn oneshot_response(run_id: Uuid, handle: &Arc<RunHandle>) -> Result<Response, ServerError> {
392	    // Cancel the run if the client disconnects while we await the result.
393	    let _disconnect = handle.cancel.clone().drop_guard();
394	
395	    // NOTE: the event log is capped at `max_events_per_run` events; `output`
396	    // in the response reflects only the events retained by the ring buffer.
397	    let events: Vec<AgentEvent> = handle.log.subscribe(0).collect().await;
398	
399	    // If the run failed to *start*, surface a 500 rather than a 200 envelope.
400	    if let Some(msg) = handle
401	        .start_error
402	        .lock()
403	        .expect("start_error mutex poisoned")
404	        .clone()
405	    {
406	        return Err(ServerError::RunStart(msg));
407	    }
408	
409	    let mut response = Json(RunResponse::from_events(run_id, events)).into_response();
410	    insert_run_id(response.headers_mut(), run_id);
411	    Ok(response)
412	}
413	
414	/// Serialize an [`AgentEvent`] into an SSE [`Event`], tagging the SSE `event:`
415	/// field with the event's serde `type` discriminant and carrying the full event
416	/// JSON as the `data:` payload.
417	fn to_sse_event(ev: &AgentEvent) -> Event {
418	    let value = serde_json::to_value(ev).expect("AgentEvent serializes");
419	    let event = match value.get("type").and_then(serde_json::Value::as_str) {
420	        Some(tag) => Event::default().event(tag),
421	        None => Event::default(),
422	    };
423	    event
424	        .json_data(&value)
425	        .expect("serde_json::Value serializes without error")
426	}
427	
428	/// Insert the `X-Run-Id` response header.
429	fn insert_run_id(headers: &mut HeaderMap, run_id: Uuid) {
430	    let value =
431	        HeaderValue::from_str(&run_id.to_string()).expect("uuid is always a valid header value");
432	    headers.insert("x-run-id", value);
433	}
434

